    $where='';$args=[];if($q!==''){$like='%'.str_replace(['\\','%','_'],['\\\\','\\%','\\_'],$q).'%';$where=" WHERE at LIKE ? ESCAPE '\\' OR actor LIKE ? ESCAPE '\\' OR action LIKE ? ESCAPE '\\' OR target LIKE ? ESCAPE '\\' OR ip LIKE ? ESCAPE '\\'";$args=array_fill(0,5,$like);}
